/**
 * Handle a TRIM on a treefiles export: fully covered blocks have their
 * file removed; partially covered blocks get the trimmed bytes zeroed.
 */
void trim_treefiles(char *name, off_t size, off_t from, size_t len) {
	off_t end = from + len;
	off_t pos;

	for(pos = from & ~((off_t)TREEPAGESIZE - 1); pos < end; pos += TREEPAGESIZE) {
		off_t blkoff = from > pos ? from - pos : 0;
		off_t blklen = end - pos < TREEPAGESIZE ? end - pos : TREEPAGESIZE;
		blklen -= blkoff;

		if(blkoff == 0 && blklen == TREEPAGESIZE) {
			delete_treefile(name, size, pos);
		} else {
			char zeroes[TREEPAGESIZE];
			int fd;

			fd = open_treefile(name, O_RDWR, size, pos, NULL);
			if(fd < 0)
				continue; /* block not on disk, already "zeroes" */
