arguments.content:
/*
 * Tree files support.
 *
 * An export with the treefiles option stores its data in a tree of
 * directories rooted at the exportname (which, for such exports, is a
 * directory rather than a file). Every leaf file in the tree holds
 * exactly one TREEPAGESIZE block of the export, and every directory
 * holds at most TREEDIRSIZE files or subdirectories, so larger exports
 * get more levels of nesting. The location of the block containing a
 * given export offset is computed by construct_path(). Blocks that
 * have never been written have no file on disk and read back as
 * zeroes; trimming a block removes its file again.
 */

#include "config.h"
#include "lfs.h"

#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>

#include <sys/stat.h>
#include <sys/types.h>

#include "cliserv.h"
#include "nbdsrv.h"
#include "treefiles.h"

/*
 * Number of "/XXXX" path components that can be added by
 * construct_path(). An off_t-sized export needs at most six levels of
 * nesting (1024^6 blocks > OFFT_MAX / TREEPAGESIZE), so this leaves
 * ample headroom.
 */
#define TREE_PATH_EXTRA 64

/**
 * Compute the path of the block file holding the data at a given
 * offset of a treefiles export.
 *
 * @param name the exportname (root of the tree); on return, this
 *        buffer holds the full path of the block file
 * @param lenmax the size of the name buffer
 * @param size the total size of the export, in bytes
 * @param pos the offset into the export whose block file we want
 * @param ppos if not NULL, set to the offset of pos within the block
 *        file
 **/
void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	off_t nblocks;
	off_t block;
	off_t capacity = TREEDIRSIZE;
	off_t divisor;
	int depth = 0;
	int len;

	nblocks = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	block = pos / TREEPAGESIZE;

	/*
	 * Compute the number of levels of nesting we need so that no
	 * directory ever holds more than TREEDIRSIZE entries.
	 */
	while (capacity < nblocks) {
		capacity *= TREEDIRSIZE;
		depth++;
	}

	/* every level adds "/XXXX", plus a trailing NUL */
	len = strlen(name);
	if (len + (depth + 1) * 5 + 1 > lenmax)
		err("construct_path: filename buffer too small");

	divisor = capacity / TREEDIRSIZE;
	while (depth-- > 0) {
		snprintf(name + len, lenmax - len, "/%04d",
			 (int)((block / divisor) % TREEDIRSIZE));
		len += 5;
		divisor /= TREEDIRSIZE;
	}
	snprintf(name + len, lenmax - len, "/%04d", (int)(block % TREEDIRSIZE));

	if (ppos)
		*ppos = pos % TREEPAGESIZE;
}

/**
 * Create all directories named in a path.
 *
 * @param path the path whose directory components should be created.
 *        The string is truncated at each '/' temporarily, but restored
 *        before returning.
 **/
void mkdir_path(char *path) {
	char *p;

	if (!path || !*path)
		return;

	for (p = path + 1; *p; p++) {
		if (*p != '/')
			continue;
		*p = '\0';
		if (mkdir(path, 0700) && errno != EEXIST)
			err("mkdir_path: could not create directory: %m");
		*p = '/';
	}
	if (mkdir(path, 0700) && errno != EEXIST)
		err("mkdir_path: could not create directory: %m");
}

/**
 * Open the block file holding the data at a given offset of a
 * treefiles export, creating the file (and any directories leading up
 * to it) if O_CREAT is set in mode.
 *
 * @param name the exportname (root of the tree)
 * @param mode open mode, as for open(2)
 * @param size the total size of the export, in bytes
 * @param pos the offset into the export whose block file we want
 * @param mutex if not NULL, held while the directories and file are
 *        being created, so that concurrent callers don't trip over
 *        each other
 * @return a file descriptor on success, -1 on failure (with errno set
 *         appropriately)
 **/
int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	char *path;
	char *slash;
	int lenmax;
	int fd;

	lenmax = strlen(name) + TREE_PATH_EXTRA;
	path = malloc(lenmax);
	if (!path)
		err("open_treefile: out of memory");
	strcpy(path, name);
	construct_path(path, lenmax, size, pos, NULL);

	if (mode & O_CREAT) {
		if (mutex)
			pthread_mutex_lock(mutex);
		/* create the directories leading up to the file */
		slash = strrchr(path, '/');
		*slash = '\0';
		mkdir_path(path);
		*slash = '/';
		fd = open(path, mode, 0600);
		if (mutex)
			pthread_mutex_unlock(mutex);
	} else {
		fd = open(path, mode);
	}
	free(path);

	return fd;
}

/**
 * Delete the block file holding the data at a given offset of a
 * treefiles export, if it exists.
 *
 * @param name the exportname (root of the tree)
 * @param size the total size of the export, in bytes
 * @param pos the offset into the export whose block file we want gone
 **/
void delete_treefile(char *name, off_t size, off_t pos) {
	char *path;
	int lenmax;

	lenmax = strlen(name) + TREE_PATH_EXTRA;
	path = malloc(lenmax);
	if (!path)
		err("delete_treefile: out of memory");
	strcpy(path, name);
	construct_path(path, lenmax, size, pos, NULL);

	/* the file may not exist if the block was never written */
	if (unlink(path) && errno != ENOENT)
		msg(LOG_WARNING, "could not remove treefile %s: %s", path,
		    strerror(errno));
	free(path);
}

/**
 * Handle a TRIM request on a treefiles export. Blocks that are fully
 * covered by the trimmed range have their file removed; for partially
 * covered blocks, the trimmed bytes are zeroed.
 *
 * @param name the exportname (root of the tree)
 * @param size the total size of the export, in bytes
 * @param from the start of the trimmed range
 * @param len the length of the trimmed range
 **/
void trim_treefiles(char *name, off_t size, off_t from, size_t len) {
	off_t end = from + len;
	off_t pos;

	for (pos = from & ~((off_t)TREEPAGESIZE - 1); pos < end;
	     pos += TREEPAGESIZE) {
		off_t blkoff = from > pos ? from - pos : 0;
		off_t blklen = end - pos < TREEPAGESIZE ? end - pos :
			TREEPAGESIZE;

		blklen -= blkoff;
		if (blkoff == 0 && blklen == TREEPAGESIZE) {
			delete_treefile(name, size, pos);
		} else {
			char zeroes[TREEPAGESIZE];
			int fd;

			/*
			 * The block isn't fully covered, so we can't drop
			 * the file; zero the trimmed part instead. If the
			 * file doesn't exist, the block already reads back
			 * as zeroes.
			 */
			fd = open_treefile(name, O_RDWR, size, pos, NULL);
			if (fd < 0)
				continue;
			memset(zeroes, 0, TREEPAGESIZE);
			if (pwrite(fd, zeroes, blklen, blkoff) < 0)
				msg(LOG_WARNING,
				    "could not zero trimmed treefile: %s",
				    strerror(errno));
			close(fd);
		}
	}
}

