/**
 * Read an amount of bytes at a given offset from a treefiles export.
 * Reads at most the remainder of the TREEPAGESIZE block containing
 * the offset; the caller is expected to call us again for the
 * remainder of the request (rawexpread_fully does this). Blocks that
 * were never written read back as zeroes.
 *
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @param client The client we're serving for
 * @return The number of bytes actually read, or -1 in case of an
 * error.
 **/
static ssize_t treefiles_read(off_t a, char *buf, size_t len, CLIENT *client) {
	off_t foffset;
	size_t maxbytes;
	ssize_t retval;
	int fd;

	foffset = a % TREEPAGESIZE;
	maxbytes = TREEPAGESIZE - foffset;
	if(len > maxbytes)
		len = maxbytes;

	DEBUG("(TREEFILES READ at %llu len %u), ", (long long unsigned int)a, (unsigned int)len);

	fd = open_treefile(client->exportname, O_RDONLY, client->exportsize, a, NULL);
	if(fd < 0) {
		if(errno != ENOENT)
			return -1;
		/* the block was never written, it reads back as zeroes */
		memset(buf, 0, len);
		return len;
	}
	retval = pread(fd, buf, len, foffset);
	close(fd);
	if(retval >= 0 && (size_t)retval < len) {
		/*
		 * the final block of the export may be partial; its
		 * tail reads back as zeroes
		 */
		memset(buf + retval, 0, len - retval);
		retval = len;
	}

	return retval;
}

/**
 * Write an amount of bytes at a given offset to a treefiles export.
 * Writes at most the remainder of the TREEPAGESIZE block containing
 * the offset; the caller is expected to call us again for the
 * remainder of the request (rawexpwrite_fully does this).
 *
 * @param a The offset where the write should start
 * @param buf The buffer to write from
 * @param len The length of buf
 * @param client The client we're serving for
 * @param fua Flag to indicate 'Force Unit Access'
 * @return The number of bytes actually written, or -1 in case of an error
 **/
static ssize_t treefiles_write(off_t a, char *buf, size_t len, CLIENT *client, int fua) {
	off_t foffset;
	size_t maxbytes;
	ssize_t retval;
	int fd;

	foffset = a % TREEPAGESIZE;
	maxbytes = TREEPAGESIZE - foffset;
	if(len > maxbytes)
		len = maxbytes;

	DEBUG("(TREEFILES WRITE to %llu len %u fua %d), ", (long long unsigned int)a, (unsigned int)len, fua);

	fd = open_treefile(client->exportname, O_RDWR | O_CREAT, client->exportsize, a, &treefiles_mutex);
	if(fd < 0)
		return -1;
	retval = pwrite(fd, buf, len, foffset);
	if(retval > 0) {
		if(client->server->flags & F_SYNC) {
			fsync(fd);
		} else if(fua) {
			fdatasync(fd);
		}
	}
	close(fd);

	return retval;
}

