/*
 * Minimal NBD client to end-to-end verify a treefiles export:
 * newstyle handshake, read of unwritten blocks (must be zeroes),
 * unaligned + cross-block writes, read-back, reconnect persistence,
 * full-block trim (blocks must read back as zeroes afterwards) and
 * partial-block trim (trimmed bytes zeroed, rest preserved).
 *
 * Usage: treecheck <host> <port> <exportname>
 */
#define _DEFAULT_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <netdb.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define INIT_PASSWD "NBDMAGIC"
#define CLISERV_MAGIC 0x00420281861253LL
#define OPTS_MAGIC 0x49484156454F5054LL
#define NBD_OPT_EXPORT_NAME 1
#define NBD_FLAG_C_FIXED_NEWSTYLE (1 << 0)
#define NBD_REQUEST_MAGIC 0x25609513
#define NBD_REPLY_MAGIC 0x67446698
#define NBD_CMD_READ 0
#define NBD_CMD_WRITE 1
#define NBD_CMD_DISC 2
#define NBD_CMD_TRIM 4

struct nbd_request {
	uint32_t magic;
	uint32_t type;
	uint64_t cookie;
	uint64_t from;
	uint32_t len;
} __attribute__((packed));

struct nbd_reply {
	uint32_t magic;
	uint32_t error;
	uint64_t cookie;
} __attribute__((packed));

static int sock = -1;
static int failures = 0;

static uint64_t htonll(uint64_t a) {
	return ((uint64_t)htonl(a & 0xffffffff) << 32) | htonl(a >> 32);
}

static uint64_t ntohll(uint64_t a) {
	return ((uint64_t)ntohl(a & 0xffffffff) << 32) | ntohl(a >> 32);
}

static void rd(void *buf, size_t len) {
	size_t off = 0;
	while (off < len) {
		ssize_t r = read(sock, (char *)buf + off, len - off);
		if (r <= 0) {
			fprintf(stderr, "FATAL: short read: %s\n",
				strerror(errno));
			exit(2);
		}
		off += r;
	}
}

static void wr(const void *buf, size_t len) {
	size_t off = 0;
	while (off < len) {
		ssize_t r = write(sock, (const char *)buf + off, len - off);
		if (r <= 0) {
			fprintf(stderr, "FATAL: short write: %s\n",
				strerror(errno));
			exit(2);
		}
		off += r;
	}
}

static void check(int cond, const char *what) {
	if (cond) {
		printf("ok: %s\n", what);
	} else {
		printf("FAIL: %s\n", what);
		failures++;
	}
}

static uint64_t handshake(const char *name, uint16_t *eflags) {
	char buf8[8];
	uint64_t magic64, size;
	uint32_t tmp32;
	uint16_t gflags, cflags, namelen;
	char zeroes[124];

	rd(buf8, 8);
	check(!memcmp(buf8, INIT_PASSWD, 8), "initial magic");
	rd(&magic64, 8);
	check(ntohll(magic64) == CLISERV_MAGIC, "cliserv magic");
	rd(&magic64, 8);
	check(ntohll(magic64) == OPTS_MAGIC, "opts magic (newstyle)");
	rd(&gflags, 2);

	cflags = htons(NBD_FLAG_C_FIXED_NEWSTYLE);
	wr(&cflags, 2);

	magic64 = htonll(OPTS_MAGIC);
	wr(&magic64, 8);
	tmp32 = htonl(NBD_OPT_EXPORT_NAME);
	wr(&tmp32, 4);
	namelen = strlen(name);
	tmp32 = htonl(namelen);
	wr(&tmp32, 4);
	wr(name, namelen);

	rd(&size, 8);
	size = ntohll(size);
	rd(eflags, 2);
	rd(zeroes, sizeof(zeroes));
	return size;
}

static void do_req(uint32_t type, uint64_t from, uint32_t len,
		   void *data, int expect_error) {
	struct nbd_request req;
	struct nbd_reply rep;

	req.magic = htonl(NBD_REQUEST_MAGIC);
	req.type = htonl(type);
	req.cookie = htonll(from ^ ((uint64_t)len << 32));
	req.from = htonll(from);
	req.len = htonl(len);
	wr(&req, sizeof(req));
	if (type == NBD_CMD_WRITE)
		wr(data, len);

	rd(&rep, sizeof(rep));
	check(ntohl(rep.magic) == NBD_REPLY_MAGIC, "reply magic");
	check(rep.cookie == req.cookie, "reply cookie");
	if (expect_error) {
		check(rep.error != 0, "reply carries expected error");
	} else {
		check(rep.error == 0, "reply error is zero");
	}
	if (type == NBD_CMD_READ && !expect_error && rep.error == 0)
		rd(data, len);
}

static void fill(char *buf, size_t len, uint64_t seed) {
	size_t i;
	for (i = 0; i < len; i++)
		buf[i] = (char)((i * 7 + seed * 13 + (i >> 8)) & 0xff);
}

