	do_req(NBD_CMD_WRITE, 0, 8000, buf, 0);
	/* another one, deep in the export and crossing a block boundary */
	fill(buf, 5000, 2);
	do_req(NBD_CMD_WRITE, 500000, 5000, buf, 0);
	/* one in a block that lives a directory level deeper (block 1500) */
	fill(buf, BLK, 3);
	do_req(NBD_CMD_WRITE, 1500 * BLK, BLK, buf, 0);

	/* read everything back */
	memset(buf, 0, 8000);
	do_req(NBD_CMD_READ, 0, 8000, buf, 0);
	fill(expect, 8000, 1);
	check(!memcmp(buf, expect, 8000), "read-back of first write");

	memset(buf, 0, 5000);
	do_req(NBD_CMD_READ, 500000, 5000, buf, 0);
	fill(expect, 5000, 2);
	check(!memcmp(buf, expect, 5000), "read-back of second write");

	memset(buf, 0, BLK);
	do_req(NBD_CMD_READ, 1500 * BLK, BLK, buf, 0);
	fill(expect, BLK, 3);
	check(!memcmp(buf, expect, BLK), "read-back of third write");

	/* read crossing a block boundary mid-pattern */
	memset(buf, 0, 32);
	do_req(NBD_CMD_READ, BLK - 10, 32, buf, 0);
	fill(expect, 8000, 1);
	check(!memcmp(buf, expect + (BLK - 10), 32),
	      "cross-block read matches pattern");

	/* out-of-bounds write must fail */
	do_req(NBD_CMD_WRITE, size - 10, 64, buf, 1);

	/* disconnect and reconnect: data must persist across connections */
	do_req(NBD_CMD_DISC, 0, 0, NULL, 0);
	close(sock);

	sock = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
	if (sock < 0 || connect(sock, res->ai_addr, res->ai_addrlen) < 0) {
		perror("reconnect");
		return 2;
	}
	size = handshake(export, &eflags);

	memset(buf, 0, 5000);
	do_req(NBD_CMD_READ, 500000, 5000, buf, 0);
	fill(expect, 5000, 2);
	check(!memcmp(buf, expect, 5000), "data persists after reconnect");

	/* trim the two fully-covered blocks at the start */
	do_req(NBD_CMD_TRIM, 0, 2 * BLK, NULL, 0);
	memset(buf, 0xaa, 2 * BLK);
	do_req(NBD_CMD_READ, 0, 2 * BLK, buf, 0);
	memset(expect, 0, 2 * BLK);
	check(!memcmp(buf, expect, 2 * BLK),
	      "fully trimmed blocks read as zeroes");

	/* the third write must have survived the trim of other blocks */
	memset(buf, 0, BLK);
	do_req(NBD_CMD_READ, 1500 * BLK, BLK, buf, 0);
	fill(expect, BLK, 3);
	check(!memcmp(buf, expect, BLK), "unrelated block survives trim");

	/* partial trim inside the second write:
	 * [501000, 504000) trimmed, [500000,501000) and [504000,505000)
	 * must be preserved */
	do_req(NBD_CMD_TRIM, 501000, 3000, NULL, 0);
	memset(buf, 0, 5000);
	do_req(NBD_CMD_READ, 500000, 5000, buf, 0);
	fill(expect, 5000, 2);
	memset(expect + 1000, 0, 3000);
	check(!memcmp(buf, expect, 5000),
	      "partial trim zeroes only trimmed bytes");

	do_req(NBD_CMD_DISC, 0, 0, NULL, 0);

	printf(failures ? "FAILURES: %d\n" : "ALL CHECKS PASSED\n", failures);
	return failures ? 1 : 0;
}

